398	    /// Go through all polygon nodes and cure small local self-intersections.
399	    fn cure_local_intersections(&mut self, start: usize) -> usize {
400	        let mut start = start;
401	        let mut p = start;
402	
403	        loop {
404	            let a = self.nodes[p].prev;
405	            let pn = self.nodes[p].next;
406	            let b = self.nodes[pn].next;
407	
408	            // a self-intersection where edge (v[i-1],v[i]) intersects (v[i+1],v[i+2])
409	            if !self.equals(a, b)
410	                && self.intersects(a, p, pn, b)
411	                && self.locally_inside(a, b)
412	                && self.locally_inside(b, a)
413	            {
414	                self.indices.push(self.nodes[a].i);
415	                self.indices.push(self.nodes[p].i);
416	                self.indices.push(self.nodes[b].i);
417	
418	                // remove two nodes involved; `pn` is still `p.next` after the first
419	                // removal, which only rewires the neighbours
420	                self.remove_node(p);
421	                self.remove_node(pn);
422	
423	                p = b;
424	                start = b;
425	            }
426	
427	            p = self.nodes[p].next;
428	            if p == start {
429	                break;
430	            }
431	        }
432	
433	        self.filter_points(p, NIL)
434	    }
435	
436	    /// Try splitting polygon into two and triangulate them independently.
437	    fn split_earcut(&mut self, start: usize) {
438	        // look for a valid diagonal that divides the polygon into two
439	        let mut a = start;
440	        loop {
441	            let an = self.nodes[a].next;
442	            let mut b = self.nodes[an].next;
443	
444	            while b != self.nodes[a].prev {
445	                if self.nodes[a].i != self.nodes[b].i && self.is_valid_diagonal(a, b) {
446	                    // split the polygon in two by the diagonal
447	                    let mut c = self.split_polygon(a, b);
448	
449	                    // filter colinear points around the cuts
450	                    let a_next = self.nodes[a].next;
451	                    let a2 = self.filter_points(a, a_next);
452	                    let c_next = self.nodes[c].next;
453	                    c = self.filter_points(c, c_next);
454	
455	                    // run earcut on each half
456	                    self.earcut_linked(a2, 0);
457	                    self.earcut_linked(c, 0);
458	                    return;
459	                }
460	                b = self.nodes[b].next;
461	            }
462	            a = self.nodes[a].next;
463	            if a == start {
464	                return;
465	            }
466	        }
467	    }
468	
469	    /// Link every hole into the outer loop, producing a single-ring polygon
470	    /// without holes.
471	    fn eliminate_holes(&mut self, points: &[Vec<[f64; 2]>], outer_node: usize) -> usize {
472	        let mut queue: Vec<usize> = Vec::new();
473	
474	        for ring in &points[1..] {
475	            let list = self.linked_list(ring, false);
476	            if list != NIL {
477	                if list == self.nodes[list].next {
478	                    self.nodes[list].steiner = true;
479	                }
480	                let leftmost = self.get_leftmost(list);
481	                queue.push(leftmost);
482	            }
483	        }
484	
485	        {
486	            let nodes = &self.nodes;
487	            queue.sort_by(|&a, &b| {
488	                nodes[a]
489	                    .x
490	                    .partial_cmp(&nodes[b].x)
491	                    .unwrap_or(std::cmp::Ordering::Equal)
492	            });
493	        }
494	
495	        // process holes from left to right
496	        let mut outer_node = outer_node;
497	        for hole in queue {
498	            outer_node = self.eliminate_hole(hole, outer_node);
499	        }
500	
501	        outer_node
502	    }
503	
504	    /// Find a bridge between vertices that connects a hole with an outer ring and
505	    /// link it.
506	    fn eliminate_hole(&mut self, hole: usize, outer_node: usize) -> usize {
507	        let bridge = self.find_hole_bridge(hole, outer_node);
508	        if bridge == NIL {
509	            return outer_node;
510	        }
511	
512	        let bridge_reverse = self.split_polygon(bridge, hole);
513	
514	        // filter collinear points around the cuts
515	        let br_next = self.nodes[bridge_reverse].next;
516	        self.filter_points(bridge_reverse, br_next);
517	        let b_next = self.nodes[bridge].next;
518	        self.filter_points(bridge, b_next)
519	    }
520	
521	    /// David Eberly's algorithm for finding a bridge between a hole and an outer
522	    /// polygon.
523	    fn find_hole_bridge(&self, hole: usize, outer_node: usize) -> usize {
524	        let mut p = outer_node;
525	        let hx = self.nodes[hole].x;
526	        let hy = self.nodes[hole].y;
527	        let mut qx = f64::NEG_INFINITY;
528	        let mut m = NIL;
529	
530	        // find a segment intersected by a ray from the hole's leftmost vertex to
531	        // the left; segment's endpoint with lesser x will be potential connection
532	        // vertex
533	        loop {
534	            let pn = self.nodes[p].next;
535	            let (py, pny) = (self.nodes[p].y, self.nodes[pn].y);
536	            if hy <= py && hy >= pny && pny != py {
537	                let (px, pnx) = (self.nodes[p].x, self.nodes[pn].x);
538	                let x = px + (hy - py) / (pny - py) * (pnx - px);
539	                if x <= hx && x > qx {
540	                    qx = x;
541	                    m = if px < pnx { p } else { pn };
542	                    if x == hx {
543	                        // hole touches outer segment; pick leftmost endpoint
544	                        return m;
545	                    }
546	                }
547	            }
548	            p = pn;
549	            if p == outer_node {
550	                break;
551	            }
552	        }
553	
554	        if m == NIL {
555	            return NIL;
556	        }
557	
558	        // look for points inside the triangle of hole vertex, segment intersection
559	        // and endpoint; if there are no points found, we have a valid connection;
560	        // otherwise choose the vertex of the polygon with the least x
561	        let stop = m;
562	        let mut tan_min = f64::INFINITY;
563	        let mx = self.nodes[m].x;
564	        let my = self.nodes[m].y;
565	
566	        p = m;
567	        loop {
568	            let (px, py) = (self.nodes[p].x, self.nodes[p].y);
569	            if hx >= px
570	                && px >= mx
571	                && hx != px
572	                && self.point_in_triangle(
573	                    if hy < my { hx } else { qx },
574	                    hy,
575	                    mx,
576	                    my,
577	                    if hy < my { qx } else { hx },
578	                    hy,
579	                    px,
580	                    py,
581	                )
582	            {
583	                let tan_cur = (hy - py).abs() / (hx - px); // tangential
584	
585	                if self.locally_inside(p, hole)
586	                    && (tan_cur < tan_min
587	                        || (tan_cur == tan_min
588	                            && (px > self.nodes[m].x || self.sector_contains_sector(m, p))))
589	                {
590	                    m = p;
591	                    tan_min = tan_cur;
592	                }
593	            }
594	
595	            p = self.nodes[p].next;
596	            if p == stop {
597	                break;
598	            }
599	        }
600	
601	        m
602	    }
603	}

     1	//! Node of the circular doubly-linked list the ear-clipping triangulator walks.
     2	//!
     3	//! The reference implementation links heap-allocated nodes with raw pointers.
     4	//! Here the nodes live in a single arena (`Vec<Node>`) and the links are arena
     5	//! indices, with [`NIL`] standing in for a null pointer. Indices stay valid
     6	//! across arena growth, which pointers into a `Vec` would not.
     7	
     8	/// Sentinel used where the reference implementation stores a null `Node*`.
     9	pub const NIL: usize = usize::MAX;
    10	
    11	#[derive(Clone, Copy)]
    12	pub struct Node {
    13	    /// Index of the vertex within the flattened input.
    14	    pub i: u32,
    15	    pub x: f64,
    16	    pub y: f64,
    17	
    18	    /// Previous and next vertex nodes in a polygon ring.
    19	    pub prev: usize,
    20	    pub next: usize,
    21	
    22	    /// Z-order curve value.
    23	    pub z: i32,
    24	
    25	    /// Previous and next nodes in z-order.
    26	    pub prev_z: usize,
    27	    pub next_z: usize,
    28	
    29	    /// Indicates whether this is a steiner point.
    30	    pub steiner: bool,
    31	}
    32	
    33	impl Node {
    34	    pub fn new(i: u32, x: f64, y: f64) -> Self {
    35	        Node {
    36	            i,
    37	            x,
    38	            y,
